use thinkthen::{Engine, Question};
let tt = Engine::from_env()?;
let teams = ["billing", "shipping", "account"];
let owner = Question::choose("Which team owns this?",
    &teams)?.build()?;
let texts = ["My card was charged twice.",
    "The courier lost my parcel.",
    "I cannot reset my password."];
// the compiler makes you handle "not sure"
for text in texts {
    match tt.choose(&owner, text)? {
        Some(team) => println!("{team}: {text}"),
        None => println!("a person: {text}"),
    }
}
